import{describe,it,expect}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));describe("Cuddalore Ancient Port Explorer Tests",()=>{it("HTML contains all required sections: historical overview, trade significance, nearby heritage sites, timeline, gallery, and references",()=>{const e=readFileSync(resolve(__dirname,"../../cuddalore-port-explorer/index.html"),"utf-8");expect(e).toContain('id="overview"'),expect(e).toContain('id="trade-significance"'),expect(e).toContain('id="heritage-sites"'),expect(e).toContain('id="timeline"'),expect(e).toContain('id="gallery"'),expect(e).toContain('id="references"'),expect(e).toContain("Cuddalore"),expect(e).toContain("Koodaloor"),expect(e).toContain("Fort St. David"),expect(e).toContain("Padaleeswarar")}),it("CSS stylesheet exists and defines port styling tokens",()=>{const e=readFileSync(resolve(__dirname,"../../cuddalore-port-explorer/style.css"),"utf-8");expect(e).toContain("--port-dark"),expect(e).toContain("--port-gold"),expect(e).toContain("--port-teal"),expect(e).toContain(".port-main"),expect(e).toContain(".port-hero")}),it("JavaScript module initializes clean and registers search items",()=>{const e=readFileSync(resolve(__dirname,"../../cuddalore-port-explorer/script.js"),"utf-8");expect(e).toContain("initCuddalorePortExplorer"),expect(e).toContain("setupGalleryModal"),expect(e).toContain("cuddalore-port-explorer/index.html")}),it("Landing Page Integration: Ancient Ports explorer landing page includes Cuddalore card",()=>{const e=readFileSync(resolve(__dirname,"../../ancient-ports-explorer/index.html"),"utf-8");expect(e).toContain("Cuddalore Ancient Port"),expect(e).toContain("../cuddalore-port-explorer/index.html")})});